def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    own = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n == 1:
        return 'C' if opp[0] == 'C' else 'D'

    total_own_d = own.count('D')
    total_opp_d = opp.count('D')

    recent_len = 15 if n > 15 else n
    recent_start = n - recent_len
    recent_opp_d = 0
    for i in range(recent_start, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    c_after_d = 0
    d_after_d = 0
    d_after_c = 0
    rc_after_d = 0
    rd_after_c = 0

    trans_start = n - recent_len
    if trans_start < 1:
        trans_start = 1

    for i in range(1, n):
        if own[i - 1] == 'C':
            if opp[i] == 'D':
                d_after_c += 1
        else:
            if opp[i] == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

        if i >= trans_start:
            if own[i - 1] == 'C':
                if opp[i] == 'D':
                    rd_after_c += 1
            else:
                if opp[i] == 'C':
                    rc_after_d += 1

    exploit_evidence = False
    if total_opp_d == 0:
        if total_own_d > 0 and c_after_d > 0:
            exploit_evidence = True
    else:
        if (
            d_after_c <= 1 and
            rd_after_c <= 1 and
            c_after_d >= d_after_d + d_after_c + 3 and
            total_opp_d * 5 <= n * 2 and
            recent_opp_d <= max(1, recent_len // 3) and
            rc_after_d >= 2
        ):
            exploit_evidence = True

    if total_opp_d == 0:
        if exploit_evidence:
            return 'D'
        if total_own_d == 0:
            if n >= 6:
                return 'D'
            return 'C'
        return 'C'

    if d_after_c >= 3 or (rd_after_c >= 2 and total_opp_d > 3):
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if total_opp_d * 3 > n * 2 or recent_opp_d * 3 > recent_len * 2:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    if recent_len >= 6 and recent_opp_d >= recent_len - 1:
        return 'D'

    last_opp = opp[-1]
    last_own = own[-1]

    if last_opp == 'D':
        if last_own == 'C':
            if n >= 3 and own[-2] == 'D':
                if recent_opp_d <= max(2, recent_len // 3) and rd_after_c <= 1:
                    if rng.random() < 0.70:
                        return 'C'
                return 'D'
            else:
                if total_opp_d * 3 <= n and recent_opp_d <= 2 and rng.random() < 0.35:
                    return 'C'
                return 'D'
        else:
            if recent_opp_d >= max(3, recent_len // 2):
                return 'D'
            if total_opp_d * 3 <= n or recent_opp_d <= 2:
                return 'C'
            if rng.random() < 0.55:
                return 'D'
            return 'C'

    if exploit_evidence:
        return 'D'

    if last_own == 'D':
        if recent_opp_d <= 1 and total_opp_d * 5 <= n * 2 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if total_opp_d <= 2 and n >= 25 and rng.random() < 0.01:
        return 'D'

    return 'C'
